-- ~/.config/rex/init.lua on the Mac client.
-- Reload after edits:  rex config check && rex config reload
--
-- The host label and ssh alias come from host.lua (generated by install.sh,
-- git-ignored), so no machine names live in this repo.

local ok, host = pcall(require, "host")
if not ok then host = { label = "devvm", ssh = "devvm" } end

-- The dev VM as a first-class host.
-- ssh:// makes Rex run your system ssh (keys, agent, ~/.ssh/config, ProxyJump)
-- and find/autostart your personal Rex server on the VM. The unix socket is a
-- fallback for a manual `ssh -L` forward and is skipped when it doesn't exist.
local endpoints = {
  "ssh://" .. host.ssh,
  "unix:///tmp/rex-" .. host.label .. ".sock",
}
rex.host{ label = host.label, icon = "server", endpoints = endpoints }

require("connect")(host, endpoints)
rex.bind("alt+cmd+s", "vm_connect")

require("keys")

-- rexdiff (brew install rexdiff, then `rexdiff install`) writes rexdiff.lua
-- into ~/.config/rex; machines without it skip this.
pcall(require, "rexdiff")
